function needLogin(t){return `<h3>${t}</h3><div class="box" style="text-align:center"><p class="sub">Davom etish uchun kiring yoki roʻyxatdan oʻting</p><button class="go" style="width:100%" onclick="st.am='in';st.form='auth';draw()">Kirish / Roʻyxatdan oʻtish</button></div>`}
function ctitle(c){const own=c.owner==st.user.uid;return own?c.askerName:c.ownerName}
function msgs(){if(!st.user)return needLogin("Xabarlar");return `<h3>Xabarlar</h3>`+(st.chats.map(c=>{const own=c.owner==st.user.uid,un=c.lastBy&&c.lastBy!=st.user.uid&&c.lastT>(st.seen[c.id]||0);return `<div class="card" onclick="openC('${c.id}')"><div class="av">${own?ava(c.askerImg):ava(c.ownerImg,c.ownerAva)}</div><div class="inf"><b>${esc(ctitle(c))}</b>${own?'<span class="tag">Eʼloningizga</span>':""}<p>${esc(c.last||"Suhbat boshlandi")}</p></div>${un?'<span class="dot"></span>':""}</div>`}).join("")||'<div class="empty">Hozircha suhbat yoʻq. Nomzod eʼlonidan "Suhbat boshlash" ni bosing.</div>')}
function groupsV(){if(!st.user)return needLogin("Guruhlar");const mine=st.user.groups||[];return `<h3>Guruhlar</h3><p class="sub" style="text-align:left">Oʻz guruhingizni oching, muxlislaringizni bir joyga yigʻing va guruh chatida suhbatlashing.</p><button class="go" style="width:100%;margin-bottom:10px" onclick="newGroup()">${I("plus",16)} Yangi guruh ochish</button>`+(st.groups.map(g=>`<div class="card"><div class="av">${esc(g.ava||"👥")}</div><div class="inf"><b>${esc(g.name)}</b><p>${I("users",14)} ${g.n||1} aʼzo</p><div class="acts"><button class="go" onclick="${mine.includes(g.id)?`openG('${g.id}')`:`joinG('${g.id}')`}">${mine.includes(g.id)?"Chatga kirish":"Qoʻshilish"}</button></div></div></div>`).join("")||'<div class="empty">Hozircha guruh yoʻq. Birinchi boʻlib oching!</div>')}
function closeCh(){[UM,UP].forEach(f=>f&&f());UM=UP=null}
function syncShared(){const ch=st.chat;if(!ch||ch.t!="c")return;const c=st.chats.find(x=>x.id==ch.id);if(!c||c.asker!=st.user.uid)return;if(c.photoOk&&!UP)UP=FB.shared(ch.id,p=>{st.csh=p||{};st.cph=p.imgs||[];draw()});if(!c.photoOk&&UP){UP();UP=null;st.cph=[];st.csh={}}}
function chatMsgs(){const m=$("ms");if(!m)return;const g=st.chat.t=="g";m.innerHTML=st.cm.map(x=>`<div class="m ${x.from==st.user.uid?"me":""}">${g&&x.from!=st.user.uid?`<b>${esc(x.name||"")}</b>`:""}${esc(x.text)}<small>${tm(x.t)}</small></div>`).join("");m.scrollTop=m.scrollHeight}
function seen(id){st.seen[id]=Date.now();save()}
async function openAd(id){if(!need())return;const a=st.ads.find(x=>x.id==id);if(!a)return;if(a.uid==st.user.uid){uiAlert("Bu sizning oʻz eʼloningiz");return}const f=fb();if(!f)return;try{openC(await f.openChat(a,st.user))}catch(x){uiAlert("Suhbat ochilmadi: "+x.message)}}
function openC(id){closeCh();st.chat={t:"c",id};st.menu=false;st.cm=[];st.cph=[];seen(id);UM=FB.msgs("chats",id,m=>{st.cm=m;chatMsgs();seen(id)});syncShared();draw()}
function openG(id){closeCh();st.chat={t:"g",id};st.menu=false;st.cm=[];UM=FB.msgs("groups",id,m=>{st.cm=m;chatMsgs()});draw()}
function closeChat(){closeCh();st.chat=null;draw()}
async function joinG(id){if(!need())return;const f=fb();if(!f)return;try{await f.joinGroup(id,st.user.name);st.user.groups=[...(st.user.groups||[]),id];openG(id)}catch(x){uiAlert("Qoʻshilib boʻlmadi: "+x.message)}}
async function newGroup(){if(!need())return;const n=await uiPrompt("Yangi guruh nomi","Masalan: Andijon nomzodlari");if(!n||!n.trim())return;const f=fb();if(!f)return;try{const id=await f.newGroup(n.trim().slice(0,40),["⭐","🌙","💍","🌹","🕊️","💫"][Math.floor(Math.random()*6)],st.user.name);st.user.groups=[...(st.user.groups||[]),id];openG(id)}catch(x){uiAlert("Guruh ochilmadi: "+x.message)}}
async function leaveG(){const id=st.chat.id;if(!await uiConfirm("Guruhdan chiqasizmi?","Chiqish",true))return;try{await FB.leaveGroup(id);st.user.groups=(st.user.groups||[]).filter(x=>x!=id);closeChat()}catch(x){uiAlert(x.message)}}
async function grant(on){const id=st.chat.id;st.menu=false;try{const cc=st.chats.find(x=>x.id==id),ok=await FB.grant(id,on,cc&&cc.adId);if(!ok)uiAlert("Avval Profil boʻlimida shaxsiy rasmlaringizni yuklang (3 tagacha).","Rasm yoʻq");draw()}catch(x){uiAlert("Amal bajarilmadi: "+x.message)}}
async function report(){st.menu=false;draw();if(!await uiConfirm("Bu suhbat haqida shikoyat yuborilsinmi?","Yuborish"))return;try{await FB.report(st.chat.id);uiAlert("Shikoyatingiz yuborildi")}catch(x){uiAlert(x.message)}}
function zoom(s){const d=document.createElement("div");d.className="md";d.innerHTML=`<img src="${s}" style="max-width:100%;max-height:80vh;border-radius:16px">`;d.onclick=()=>d.remove();document.body.appendChild(d)}
function chatV(){const ch=st.chat,g=ch.t=="g",c=g?st.groups.find(x=>x.id==ch.id):st.chats.find(x=>x.id==ch.id);
 if(!c)return `<div class="ov"><div class="hd"><button onclick="closeChat()">${I("back",22)}</button><b>Yuklanmoqda...</b></div></div>`;
 const me=st.user.uid,own=!g&&c.owner==me,asker=!g&&!own;
 const title=g?c.name:(own?c.askerName:((st.csh&&st.csh.name)||c.ownerName)),av=g?esc(c.ava||"👥"):(own?ava(c.askerImg):ava(c.ownerImg,c.ownerAva));
 let menu="";if(st.menu)menu=`<div class="menu">${own?(c.photoOk?`<button onclick="grant(false)">${I("lock",16)} Ruxsatni bekor qilish</button>`:`<button onclick="grant(true)">${I("img",16)} Shaxsiy rasmlarga ruxsat berish</button>`):""}${g?(c.owner!=me?`<button onclick="leaveG()">${I("logout",16)} Guruhdan chiqish</button>`:""):`<button onclick="report()">${I("flag",16)} Shikoyat</button><button onclick="blockU()">${I("ban",16)} Bloklash</button>`}</div>`;
 const ban=own&&!c.photoOk&&!st.dis[c.id]&&st.cm.some(x=>x.from!=me)?`<div class="cons"><button class="x" onclick="st.dis['${c.id}']=1;draw()">${I("x",18)}</button><b>Shaxsiy rasm va maʼlumotlaringizni koʻrsatishga ruxsat berasizmi?</b><p style="color:var(--m);margin:4px 0 8px">Rasmlar faqat shu suhbatdosh uchun ochiladi. Istalgan payt bekor qilishingiz mumkin.</p><button class="go" onclick="grant(true)">Ruxsat berish</button></div>`:"";
 const ph=asker?(c.photoOk?`<div class="ph">${st.cph.map((x,i)=>`<img src="${x}" onclick="zoom('${x}')">`).join("")||'<small style="color:var(--m)">Yuklanmoqda...</small>'}</div>${st.csh&&st.csh.about?`<p class="sub" style="text-align:left;padding:8px 14px 0;margin:0">${esc(st.csh.about)}</p>`:""}`:`<div class="ph"><div class="lock">${I("lock",22)}</div><div class="lock">${I("lock",22)}</div><small style="color:var(--m);align-self:center">Shaxsiy rasmlar yopiq. Egasi ruxsat bersa ochiladi.</small></div>`):(own&&c.photoOk?`<div class="ph"><small style="color:var(--a)">${I("img",14)} Shaxsiy rasmlaringiz bu suhbatdoshga ochiq</small></div>`:"");
 return `<div class="ov"><div class="hd"><button onclick="closeChat()">${I("back",22)}</button><div class="av">${av}</div><b>${esc(title)}</b><button onclick="st.menu=!st.menu;draw()">${I("dots",20)}</button>${menu}</div>${ban}${ph}<div class="msgs" id="ms"></div><div class="send"><input class="in" id="mi" maxlength="1000" placeholder="Xabar yozing.." autocomplete="off" onkeydown="if(event.key=='Enter')send()"><button class="go" onclick="send()">${I("send",18)}</button></div></div>`}
async function send(){const i=$("mi"),v=i.value.trim();if(!v)return;i.value="";const ch=st.chat;try{await FB.send(ch.t=="g"?"groups":"chats",ch.id,v,st.user.name)}catch(x){i.value=v;uiAlert("Xabar yuborilmadi: "+x.message)}}
function privV(){if(!st.user)return"";return `<h3>Shaxsiy rasmlarim</h3><p class="sub" style="text-align:left;font-size:12px;margin:0 0 8px">Faqat siz ruxsat bergan suhbatdoshga koʻrinadi (3 tagacha).</p><div class="ph" style="padding:0">${st.priv.map((x,i)=>`<div style="position:relative"><img src="${x}"><button onclick="delPriv(${i})" style="position:absolute;top:-6px;right:-6px;width:22px;height:22px;border-radius:50%;background:#e5554a;color:#fff;display:grid;place-items:center">${I("x",12)}</button></div>`).join("")}${st.priv.length<3?`<div onclick="$('pp').click()">${I("plus",24)}</div>`:""}</div><input type="file" id="pp" accept="image/*" hidden onchange="addPriv(this)">`}
function addPriv(i){const f=i.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=async()=>{const c=document.createElement("canvas"),k=Math.min(1,480/Math.max(im.width,im.height));c.width=im.width*k;c.height=im.height*k;c.getContext("2d").drawImage(im,0,0,c.width,c.height);const n=[...st.priv,c.toDataURL("image/jpeg",.7)];try{await FB.setPriv(n);st.priv=n;draw()}catch(x){uiAlert("Rasm saqlanmadi: "+x.message)}};im.src=r.result};r.readAsDataURL(f)}
async function delPriv(i){const n=st.priv.filter((_,j)=>j!=i);try{await FB.setPriv(n);st.priv=n;draw()}catch(x){uiAlert(x.message)}}

const INTS=["Sayohat","Sport","Kitob","Musiqa","Oshpazlik","Texnologiya","Biznes","Sanʼat","Tabiat","Dinu maʼnaviyat","Oila","Kino","Moda","Avtomobil"];
Object.assign(st,{sw:false,swiped:{},deck:[],di:0,sv:null,csh:{}});
function togInt(x){keep();const a=st.p.ints=st.p.ints||[],i=a.indexOf(x);if(i>=0)a.splice(i,1);else if(a.length<5)a.push(x);draw()}
function toast(m){const d=document.createElement("div");d.className="toast";d.textContent=m;document.body.appendChild(d);setTimeout(()=>d.remove(),1700)}
function chatMsgs(){const m=$("ms");if(!m)return;const g=st.chat.t=="g";m.innerHTML=st.cm.map(x=>x.kind=="like"?`<div class="m ${x.from==st.user.uid?"me":""}"><span style="color:var(--r)">${I("heart",24,1)}</span> ${esc(String(x.text).replace("❤️ ",""))}<small>${tm(x.t)}</small></div>`:`<div class="m ${x.from==st.user.uid?"me":""}">${g&&x.from!=st.user.uid?`<b>${esc(x.name||"")}</b>`:""}${esc(x.text)}<small>${tm(x.t)}</small></div>`).join("");m.scrollTop=m.scrollHeight}
/* soʻrovnoma */
function surveyV(){const pr=st.user.prefs||{},s=st.sv=st.sv||{g:pr.g||"erkak",age:pr.age||"",vil:pr.vil||PL[0][0],reg:pr.reg||"",ints:[...(pr.ints||[])],pur:pr.pur||"oila"},L=(PL.find(x=>x[0]==s.vil)||PL[0])[1];if(!L.some(x=>x[0]==s.reg))s.reg=L[0][0];
 return `<div class="ov"><div class="hd"><button onclick="svSkip()">${I("x",22)}</button><b>Qisqa soʻrovnoma</b></div><div class="sheet"><p class="sub" style="text-align:left">Sizga mos nomzodlarni tavsiya qilish uchun bir daqiqa vaqt ajrating.</p>
<label>Jinsingiz</label><div class="seg"><button class="${s.g=="erkak"?"on":""}" onclick="svs('g','erkak')">Erkak</button><button class="${s.g=="ayol"?"on":""}" onclick="svs('g','ayol')">Ayol</button></div>
<label>Yoshingiz</label><input class="in" type="number" value="${s.age}" oninput="st.sv.age=+this.value">
<label>Yashash joyingiz</label><select class="in" onchange="svs('vil',this.value)">${PL.map(x=>`<option ${x[0]==s.vil?"selected":""}>${x[0]}</option>`).join("")}</select><select class="in" style="margin-top:8px" onchange="st.sv.reg=this.value">${L.map(x=>`<option ${x[0]==s.reg?"selected":""}>${x[0]}</option>`).join("")}</select>
<label>Qiziqishlaringiz (6 tagacha)</label><div class="ints">${INTS.map(x=>`<button class="ichip ${s.ints.includes(x)?"on":""}" onclick="svi('${x}')">${x}</button>`).join("")}</div>
<label>Maqsadingiz</label><div class="seg pur">${Object.keys(PUR).map(k=>`<button class="${s.pur==k?"on":""}" onclick="svs('pur','${k}')">${PUR[k][2]}</button>`).join("")}</div>
<button class="go" style="width:100%;margin-top:18px" onclick="svSave()">Saqlash</button><button class="ghost" style="width:100%;margin-top:8px" onclick="svSkip()">Keyinroq</button></div></div>`}
function svs(k,v){st.sv[k]=v;draw()}
function svi(x){const a=st.sv.ints,i=a.indexOf(x);if(i>=0)a.splice(i,1);else if(a.length<6)a.push(x);draw()}
function svSkip(){st.form=null;st.sv=null;st.afterSv=0;draw()}
async function svSave(){const s=st.sv;if(!s.age||s.age<18||s.age>80){uiAlert("Yoshingizni toʻgʻri kiriting (18+)");return}const f=fb();if(!f)return;const p={g:s.g,age:s.age,vil:s.vil,reg:s.reg,ints:s.ints,pur:s.pur};try{await f.savePrefs(p);st.user.prefs=p;st.form=null;st.sv=null;if(st.afterSv){st.afterSv=0;openSwipe()}else{toast("Saqlandi");draw()}}catch(x){uiAlert("Saqlanmadi: "+x.message)}}
/* mos nomzod algoritmi */
function score(a,pr){let s=0;if(a.reg==pr.reg)s+=45;else if(vilOf(a)==pr.vil)s+=25;s+=((a.ints||[]).filter(x=>(pr.ints||[]).includes(x)).length)*12;if(pr.pur&&a.pur==pr.pur)s+=15;const d=Math.abs((a.age||0)-(pr.age||a.age||0));s+=d<=3?10:d<=7?5:0;return s}
function pool(){const pr=st.user.prefs,tg=pr.g=="erkak"?"kelin":"kuyov";return st.ads.filter(a=>!a.anon&&a.img&&a.uid!=st.user.uid&&a.g==tg&&!(a.id in st.swiped)).map(a=>({a,s:score(a,pr)+Math.random()*3})).sort((x,y)=>y.s-x.s).map(x=>x.a)}
function openSwipe(){if(!need())return;if(!st.user.prefs){st.afterSv=1;st.sv=null;st.form="survey";draw();return}st.deck=pool();st.di=0;st.sw=true;draw()}
function closeSw(){st.sw=false;draw()}
function swipeV(){return `<div class="ov" style="background:radial-gradient(circle at 50% 0,#4a2250,var(--bg) 60%)"><div class="hd"><button onclick="closeSw()">${I("back",22)}</button><b>Juft topish</b><button onclick="st.sv=null;st.form='survey';draw()">${I("filter",20)}</button></div><div class="deck" id="deck"></div><div class="swb"><button class="swn" onclick="fly(0)">${I("x",30)}</button><button class="swl" onclick="fly(1)">${I("heart",30,1)}</button></div></div>`}
function renderDeck(){const d=$("deck");if(!d)return;const a=st.deck[st.di],b=st.deck[st.di+1],pr=st.user.prefs;
 if(!a){d.innerHTML=`<div class="empty" style="margin:auto"><p style="font-size:18px;margin-bottom:14px">Hozircha mos nomzod tugadi</p><button class="go" onclick="svReset()">Yoqmaganlarni qayta koʻrish</button></div>`;return}
 const card=(x,id,cls)=>`<div class="sc ${cls}" ${id?'id="sc"':""}><div class="sp" style="background-image:url('${x.img}')"></div><span class="mt">${Math.min(99,Math.round(score(x,pr)))}% mos</span><div class="si"><b style="font-size:24px">${esc(x.name)}, ${x.age}</b><p>${I("pin",14)} ${esc(x.reg)}</p><div class="ints">${(x.ints||[]).slice(0,4).map(i=>`<span class="tag">${esc(i)}</span>`).join("")}</div><p style="margin-top:6px">${esc((x.about||"").slice(0,90))}</p></div><div class="stamp like">YOQDI</div><div class="stamp nope">KEYINGI</div></div>`;
 d.innerHTML=(b?card(b,0,"back"):"")+card(a,1,"");bindSwipe()}
function stamp(el,dx){el.querySelector(".like").style.opacity=Math.max(0,Math.min(1,dx/100));el.querySelector(".nope").style.opacity=Math.max(0,Math.min(1,-dx/100))}
function bindSwipe(){const el=$("sc");if(!el)return;let x0=0,dx=0,on=false;
 el.onpointerdown=e=>{on=true;x0=e.clientX;dx=0;el.setPointerCapture(e.pointerId);el.style.transition="none"};
 el.onpointermove=e=>{if(!on)return;dx=e.clientX-x0;el.style.transform=`translateX(${dx}px) rotate(${dx/18}deg)`;stamp(el,dx)};
 const end=()=>{if(!on)return;on=false;if(Math.abs(dx)>100)fly(dx>0?1:0);else{el.style.transition="transform .25s";el.style.transform="";stamp(el,0)}};
 el.onpointerup=end;el.onpointercancel=end}
let flying=false;
function fly(v){const el=$("sc");if(!el||flying)return;flying=true;stamp(el,v?200:-200);el.style.transition="transform .3s,opacity .3s";el.style.transform=`translateX(${v?650:-650}px) rotate(${v?30:-30}deg)`;el.style.opacity=0;setTimeout(()=>{flying=false;decide(v)},280)}
async function decide(v){const a=st.deck[st.di];if(!a)return;st.di++;renderDeck();st.swiped[a.id]=v;
 try{await FB.swipe(a,v);if(v){if(!st.fav.includes(a.id)){st.fav.push(a.id);save();FB.saveUser({favs:st.fav}).catch(()=>{})}toast("Yurak yuborildi, sevimlilarga qoʻshildi");await FB.like(a,st.user)}}catch(x){console.error(x)}}
function svReset(){for(const k in st.swiped)if(st.swiped[k]===0)delete st.swiped[k];st.deck=pool();st.di=0;renderDeck()}

let MKL;
const pcol={color:"#f0b34a",fillOpacity:.2};
const mkPoly=P=>P.length>2?L.polygon(P,pcol):L.polyline(P,pcol);
function drawMarkers(){if(!MAP||!window.L)return;if(MKL)MKL.remove();MKL=L.layerGroup().addTo(MAP);const g={};list().forEach(a=>{const p=pl(a.reg);if(p)(g[p.lat+","+p.lng]=g[p.lat+","+p.lng]||[]).push(a)});
 Object.entries(g).forEach(([n,l])=>{L.marker(n.split(",").map(Number),{icon:L.divIcon({className:"",html:`<div class="mk">${l.length}</div>`,iconSize:[36,36]})}).addTo(MKL).on("click",()=>{if(!st.dr.on)showPlace(n)})});polyRes()}
function initMap(){const el=$("map");if(!el)return;if(!window.L){el.innerHTML='<div class="empty">Xarita kutubxonasi yuklanmadi. Internetni tekshiring va sahifani yangilang.</div>';return}
 try{if(MAP){try{MAP.remove()}catch(e){}MAP=null;MKL=null;DL=null}
 const m=MAP=L.map(el,{zoomControl:true}).setView(st.mv||[41.3,64.6],st.mz||5);
 let fails=0,prov=0;const T=[["https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png","© OpenStreetMap © CARTO"],["https://tile.openstreetmap.org/{z}/{x}/{y}.png","© OpenStreetMap"]];
 const addT=()=>{const t=L.tileLayer(T[prov][0],{maxZoom:18,attribution:T[prov][1]}).addTo(m);t.on("tileerror",()=>{if(++fails==4&&prov==0){prov=1;m.removeLayer(t);addT()}})};addT();
 drawMarkers();
 const P=st.dr.pts;if(P.length)DL=mkPoly(P).addTo(m);
 m.on("click",e=>{if(!st.dr.on)return;st.dr.pts.push([e.latlng.lat,e.latlng.lng]);if(DL)m.removeLayer(DL);DL=mkPoly(st.dr.pts).addTo(m);polyRes()});
 m.on("moveend",()=>{st.mv=[m.getCenter().lat,m.getCenter().lng];st.mz=m.getZoom()});
 setTimeout(()=>{if(MAP===m)m.invalidateSize()},200)}catch(e){el.innerHTML='<div class="empty">Xarita xatosi: '+esc(e.message)+'</div>'}}

