let PR={ad:10000,vip:20000,raise:10000},UA1,UA2,UPY,US;
st.cfg={};st.mine=[];st.mypays=[];st.pays=[];st.admin=false;st.ap={tab:"pay",reps:[],stats:null};
const fmt=n=>String(n).replace(/\B(?=(\d{3})+(?!\d))/g," ");
const KIND={ad:"Qoʻshimcha eʼlon",ad_vip:"Eʼlon + VIP",vip:"VIP TOP",raise:"Yuqoriga koʻtarish"};
const PSTAT={pending:"Kutilmoqda",approved:"Tasdiqlandi",rejected:"Rad etildi"};
function syncAds(){const me=st.user&&st.user.uid,now=Date.now(),m=a=>({...a,mine:!!me&&a.uid==me,vip:!!a.vip&&(!a.vipUntil||a.vipUntil>now)});st.mine=st.raw.filter(a=>me&&a.uid==me).map(m);st.ads=st.raw.filter(a=>a.status!="pending").map(m)}
function fav(id){const i=st.fav.indexOf(id);i<0?st.fav.push(id):st.fav.splice(i,1);save();if(st.user&&window.FB)FB.saveUser({favs:st.fav}).catch(()=>{});draw()}
function stopAll(){[UC,UG,UA1,UA2,UPY,US].forEach(f=>f&&f());UC=UG=UA1=UA2=UPY=US=null;closeCh();st.chats=[];st.groups=[];st.priv=[];st.mypays=[];st.pays=[];st.admin=false}
addEventListener("fb-ready",()=>{FB.onUser(u=>{if(!u||st.pyFor==u.uid)return;st.pyFor=u.uid;
 if(u.favs)st.fav=[...new Set([...st.fav,...u.favs])];
 US=FB.settings(c=>{st.cfg=c||{};PR=Object.assign({ad:10000,vip:20000,raise:10000},c.prices||{})});
 UPY=FB.myPays(u.uid,l=>{st.mypays=l.sort((a,b)=>b.t-a.t);if(st.tab=="prof"&&!st.form&&!st.chat)draw()});
 FB.isAdmin().then(v=>{st.admin=v;if(v){UA1=FB.allPays(l=>{st.pays=l;if(st.form=="admin"||(st.tab=="prof"&&!st.form&&!st.chat))draw()});UA2=FB.reports(l=>{st.ap.reps=l;if(st.form=="admin")draw()})}draw()})});
 FB.onUser(u=>{if(!u)st.pyFor=null})});
function paySheet(amount,id,note){const c=(st.cfg.cards||[]).filter(x=>x&&x.number),d=document.createElement("div");d.className="ov";d.style.cssText="background:#000b;justify-content:flex-end;z-index:40";
 d.innerHTML=`<div class="psh"><div style="display:flex;justify-content:space-between;align-items:center"><h3 style="margin:0">Toʻlov maʼlumotlari</h3><button class="ghost" id="px" style="width:44px;height:44px;border-radius:50%;padding:0">${I("x",20)}</button></div><p class="sub" style="text-align:left;margin:10px 0 4px">Soʻrovingiz qabul qilindi. Quyidagi kartaga toʻlovni amalga oshiring:</p><b style="font-size:24px">${fmt(amount)} soʻm</b>${c.length?c.map((x,i)=>`<div class="pcard ${/humo/i.test(x.type||"")?"hm":"uz"}"><small>${esc((x.type||"KARTA").toUpperCase())}</small><div class="pn">${esc(x.number)}</div><div class="pf"><span>${esc(x.holder||"")}</span><button data-n="${i}">${I("copy",20)}</button></div></div>`).join(""):'<div class="empty">Toʻlov rekvizitlari hali kiritilmagan. Admin bilan bogʻlaning.</div>'}<p class="sub" style="text-align:left;font-size:13px;line-height:1.5">Toʻlov izohiga kodni yozing: <b style="color:var(--a)">${esc(String(id).slice(-6).toUpperCase())}</b>. Toʻlovdan soʻng admin tekshiradi va ${esc(note)}.</p></div>`;
 document.body.appendChild(d);d.querySelector("#px").onclick=()=>d.remove();d.querySelectorAll("[data-n]").forEach(b=>b.onclick=()=>{const n=c[b.dataset.n].number.replace(/\s/g,"");(navigator.clipboard?navigator.clipboard.writeText(n):Promise.reject()).then(()=>toast("Karta raqami nusxalandi")).catch(()=>toast("Nusxalab boʻlmadi"))})}
async function pub(){keep();const p=st.p;if(!p.name||!p.age||p.age<18){uiAlert("Ism va yosh (18+) kiriting");return}const f=fb();if(!f)return;
 const free=!st.user.freeUsed,cost=(free?0:PR.ad)+(p.vip?PR.vip:0),d={name:p.anon?"Anonim":p.name,age:p.age,reg:p.reg||"Andijon shahri",vil:(pl(p.reg||"Andijon shahri")||{}).vil||"",g:p.g,pur:p.pur,about:p.anon?"":(p.about||""),ava:p.ava,img:p.img||"",vip:false,anon:!!p.anon,ints:p.ints||[],_priv:p.anon?{name:p.name,about:p.about||""}:null};
 try{let id,pid;if(free){id=await f.addAd({...d,status:"active"},true);st.user.freeUsed=true;if(p.vip)pid=await f.pay({kind:"vip",adId:id,amount:PR.vip},st.user)}else{id=await f.addAd({...d,status:"pending"});pid=await f.pay({kind:p.vip?"ad_vip":"ad",adId:id,amount:cost},st.user)}
  st.p=null;st.form=null;st.tab="home";draw();if(pid)paySheet(free?PR.vip:cost,pid,free?"eʼloningiz VIP boʻladi":"eʼloningiz faollashadi");else toast("Eʼlon joylashtirildi")}catch(x){uiAlert("Eʼlon joylashmadi: "+x.message)}}
