async function reviewAd(id,status){const a=st.raw.find(x=>x.id==id);if(!a)return;const active=status=="active";if(!await uiConfirm(active?"Eʼlon faollashtirilsinmi?":"Eʼlon rad etilsinmi?",active?"Tasdiqlash":"Rad etish",!active))return;try{await FB.upAd(id,{status,t:Date.now()});toast(active?"Eʼlon tasdiqlandi":"Eʼlon rad etildi")}catch(x){uiAlert("Amal bajarilmadi: "+x.message)}}
