const ago=t=>{const s=(Date.now()-t)/1000;return s<60?"hozir":s<3600?Math.floor(s/60)+" daq oldin":s<86400?Math.floor(s/3600)+" soat oldin":new Date(t).toLocaleDateString("uz")};
