function supV(){const S=st.sup||{},a=S.admin,ph=st.cfg.phone;return `<div class="ov"><div class="hd"><button onclick="closeSup()">${I("back",22)}</button><b>${a?esc(S.name||"Foydalanuvchi"):"Yordam xizmati"}</b></div>${a?`<p class="sub" style="text-align:left;padding:8px 14px 0;margin:0">${esc(S.email||"")}${S.contact?" · "+esc(S.contact):""}</p>`:(ph?`<div class="box" style="margin:10px 12px 0"><b>${I("phone",16)} Ishonch telefoni</b><div style="font-size:22px;font-weight:800;margin:6px 0 10px">${esc(ph)}</div><a class="go" style="display:block;text-align:center;text-decoration:none" href="tel:${esc(ph.replace(/[^\d+]/g,""))}">Qoʻngʻiroq qilish</a></div>`:"")}<div class="msgs" id="sms"></div><div class="send"><input class="in" id="smi" maxlength="1000" placeholder="${a?"Javob yozing..":"Xabaringizni yozing.."}" autocomplete="off" onkeydown="if(event.key=='Enter')supSend()"><button class="go" onclick="supSend()">${I("send",18)}</button></div></div>`}
const oldProf=prof;
prof=function(){const h=oldProf();if(!st.user)return h;const n=unN(),menu=`<div class="card" style="align-items:center" onclick="openNotif()"><div class="av">${I("bell",26)}</div><div class="inf"><b>Bildirishnomalar</b><p>${n?n+" ta yangi":"Yangi bildirishnoma yoʻq"}</p></div>${n?`<span class="tag" style="background:#e5554a;color:#fff;font-weight:800">${n}</span>`:""}</div><div class="card" style="align-items:center" onclick="openSup(st.user.uid)"><div class="av">${I("headset",26)}</div><div class="inf"><b>Yordam xizmati</b><p>Admin bilan yozishma</p></div>${supDot()?'<span class="dot"></span>':""}</div>`;return h.replace("<h3>Toʻlovlarim</h3>",menu+"<h3>Toʻlovlarim</h3>")};

/* ===== bloklash va push roʻyxatdan oʻtkazish ===== */
Object.assign(st,{bl:[],blby:[]});let UB1,UB2;
const badSet=()=>new Set([...st.bl.map(b=>b.to),...st.blby]);
function syncAds(){const me=st.user&&st.user.uid,now=Date.now(),bad=badSet(),m=a=>({...a,mine:!!me&&a.uid==me,vip:!!a.vip&&(!a.vipUntil||a.vipUntil>now)});st.mine=st.raw.filter(a=>me&&a.uid==me).map(m);st.ads=st.raw.filter(a=>a.status!="pending"&&!bad.has(a.uid)).map(m)}
function otherUid(c){return c.owner==st.user.uid?c.asker:c.owner}
const oldMsgs=msgs;
msgs=function(){const all=st.chats,bad=badSet();st.chats=all.filter(c=>!bad.has(otherUid(c)));try{return oldMsgs()}finally{st.chats=all}};
async function blockU(){const c=st.chats.find(x=>x.id==(st.chat&&st.chat.id));if(!c)return;st.menu=false;const to=otherUid(c),nm=c.owner==st.user.uid?c.askerName:c.ownerName;
 if(!await uiConfirm(`${nm} bloklansinmi? U sizga yoza olmaydi, eʼlonlarini ham koʻrmaysiz.`,"Bloklash",true)){draw();return}
 try{await FB.block(to,nm);closeChat();toast("Foydalanuvchi bloklandi")}catch(x){uiAlert("Bloklanmadi: "+x.message)}}
async function unblock(to){try{await FB.unblock(to);toast("Blokdan chiqarildi")}catch(x){uiAlert(x.message)}}
const oldProf2=prof;
prof=function(){const h=oldProf2();if(!st.user||!st.bl.length)return h;return h.replace("<h3>Mening eʼlonlarim</h3>",`<h3>Bloklanganlar</h3>${st.bl.map(b=>`<div class="card" style="align-items:center"><div class="av">${I("ban",22)}</div><div class="inf"><b>${esc(b.name||"Foydalanuvchi")}</b></div><button class="ghost" onclick="unblock('${b.to}')">Blokdan chiqarish</button></div>`).join("")}<h3>Mening eʼlonlarim</h3>`)};
async function enablePush(){if(!("Notification" in window)){uiAlert("Brauzeringiz bildirishnomalarni qoʻllamaydi");return}const r=await Notification.requestPermission();if(r=="granted"&&CFG.VAPID)FB.regPush(CFG.VAPID).catch(x=>console.error("push:",x));toast(r=="granted"?"Telefon bildirishnomalari yoqildi":"Ruxsat berilmadi");draw()}
addEventListener("fb-ready",()=>{FB.onUser(u=>{if(!u){[UB1,UB2].forEach(f=>f&&f());UB1=UB2=null;st.bl=[];st.blby=[];st.bFor=null;return}if(st.bFor==u.uid)return;st.bFor=u.uid;
 UB1=FB.blocksBy(u.uid,l=>{st.bl=l;syncAds();if(!st.form&&!st.chat)draw()});UB2=FB.blocksTo(u.uid,l=>{st.blby=l;syncAds();if(!st.form&&!st.chat)draw()});
 if("Notification" in window&&Notification.permission=="granted"&&CFG.VAPID)FB.regPush(CFG.VAPID).catch(()=>{})})});

/* ===== tahrirlash, hisobni oʻchirish, huquqiy havolalar ===== */
st.editId=null;
function postBtn(){st.editId=null;st.p=null;if(need()){st.form="post";draw()}}
const oldFormV=formV;
formV=function(){let h=oldFormV();if(st.editId&&st.form=="post")h=h.replace(/<div class="price"><label style="margin:0">.*?<\/p><\/div>/s,"").replace("Joylashtirish","Saqlash").replace("Eʼlon berish","Eʼlonni tahrirlash");return h};
const pub0=pub;pub=function(){return st.editId?saveEdit():pub0()};
async function openEdit(id){const a=st.mine.find(x=>x.id==id);if(!a)return;let pr={};if(a.anon){try{pr=await FB.adPriv(id)}catch(e){}}
 st.editId=id;st.p={g:a.g,pur:a.pur,ava:a.ava||"👰",img:a.img||null,name:a.anon?(pr.name||""):a.name,age:a.age,reg:a.reg,about:a.anon?(pr.about||""):(a.about||""),anon:!!a.anon,ints:[...(a.ints||[])],details:{...(a.profileDetails||{})},vip:false};st.form="post";draw()}
async function saveEdit(){keep();const p=st.p;if(!p.name||!p.age||p.age<18){uiAlert("Ism va yosh (18+) kiriting");return}const f=fb();if(!f)return;const reg=p.reg||"Andijon shahri";
 try{await f.updAd(st.editId,{name:p.anon?"Anonim":p.name,age:p.age,reg,vil:(pl(reg)||{}).vil||"",g:p.g,pur:p.pur,about:p.anon?"":(p.about||""),ava:p.ava,img:p.img||"",anon:!!p.anon,ints:p.ints||[],profileDetails:p.anon?{}:(p.details||{})},p.anon?{name:p.name,about:p.about||""}:null);st.editId=null;st.p=null;st.form=null;toast("Eʼlon saqlandi");draw()}catch(x){uiAlert("Saqlanmadi: "+x.message)}}
async function delAcc(){const f=fb();if(!f)return;if(!await uiConfirm("Hisobingiz, barcha eʼlonlaringiz, shaxsiy rasmlaringiz va bildirishnomalaringiz butunlay oʻchiriladi. Bu amalni qaytarib boʻlmaydi.","Hisobni oʻchirish",true))return;
 let pw="";if(f.hasPw()){pw=await uiPrompt("Parolni kiriting","Joriy parol","","password");if(!pw)return}
 try{await f.delAccount(pw);st.tab="home";toast("Hisob oʻchirildi");draw()}catch(x){uiAlert(/wrong-password|invalid-credential/.test(x.code||"")?"Parol notoʻgʻri":"Hisob oʻchirilmadi: "+(x.code||x.message))}}
const oldProf3=prof;
prof=function(){const h=oldProf3();if(!st.user)return h;return h+`<div style="text-align:center;margin:20px 0 6px;font-size:13px"><a href="privacy.html" target="_blank" style="color:var(--m)">Maxfiylik siyosati</a> · <a href="terms.html" target="_blank" style="color:var(--m)">Foydalanish shartlari</a></div><button class="ghost" style="width:100%;margin-top:8px;color:#e5554a;font-size:13px" onclick="delAcc()">Hisobni oʻchirish</button>`};
draw();
